import { describe, expect, it } from 'vitest';
import { IDLE_AFTER_MS } from '../liveActivity';

describe('eval: idle timeout', () => {
  it('is 3 minutes', () => {
    expect(IDLE_AFTER_MS).toBe(3 * 60 * 1000);
  });
});

import { describe, expect, it } from 'vitest';
import { normalizeRepoPath } from '../pathMatcher';

describe('eval: trailing slash', () => {
  it('drops trailing slashes', () => {
    expect(normalizeRepoPath('frontend/lib/')).toBe('frontend/lib');
    expect(normalizeRepoPath('./frontend/lib//')).toBe('frontend/lib');
  });
});
